from lib import *
S = SS('x55')
steps = [
    step("组装不执行。构造 Mono.fromSupplier(...).map(...).doOnNext(...),构造完成时没有任何输出——supplier、map、doOnNext 都没有执行;subscribe 之后才依次打印 supplier、map、doOnNext,最后订阅者收到 v!。对照:Mono.just(expensive(\"A\")) 在构造时 expensive 就执行了(参数是 Java 先算的,不是 Reactor 惰性);Mono.fromSupplier(() -> expensive(\"B\")) 构造时不执行,subscribe 才执行;Mono.defer(() -> Mono.just(expensive(\"C\"))) 同样推迟到订阅。", t=tl(S(1)), mark=lidx(S(1), 'expensive(A)', 'Mono.just(...) 构造完成'), done=lidx(S(1), 'supplier 被执行', 'map 被执行', 'expensive(B)', 'expensive(C)'), b=bars([['构造阶段打印的行数(fromSupplier 链)', 0, '0'], ['Mono.just(expensive()) 构造时执行 expensive 的次数', 1, '1(立即执行)'], ['Mono.fromSupplier / defer 构造时执行的次数', 0, '0']], 1, done=[0, 2], mark=[1]), kv=KV([['Mono.fromSupplier / map / doOnNext', '订阅才执行'], ['Mono.just(expr)', 'expr 在构造时就算了'], ['Mono.defer', '把构造也推迟到订阅'], ['规则', '链上没人订阅就什么都不发生']], ['Mono.just(expr)'])),
    step("每次订阅重新执行。同一个 Mono 订阅 3 次,源被执行 3 次(1、2、3);加 cache() 之后订阅 3 次,源只执行 1 次,三个订阅者都收到 1。Flux 的冷源被两个订阅者各订阅一次:源执行 2 次,订阅者 1 收到 10、11,订阅者 2 收到 20、21。share() 让两个订阅者共用一次执行:源只执行 1 次,两个订阅者各收到 10、11。", t=tl(S(2)), mark=lidx(S(2), '第 2 次', '第 3 次'), done=lidx(S(2), '第 1 次'), b=bars([['冷源订阅 3 次的执行次数', 3, '3'], ['cache() 后订阅 3 次的执行次数', 1, '1'], ['share() 两个订阅者的执行次数', 1, '1']], 3, mark=[0], done=[1, 2]), kv=KV([['冷源', '每个订阅者各执行一遍'], ['cache()', '第一次的结果被所有人共用'], ['share()', '多个订阅者共用一次上游执行'], ['后果', '订阅几次,副作用就发生几次']], ['冷源'])),
    step("丢掉返回值就等于没执行。调用 save(\"x1\") 返回 Mono<Void> 但没订阅:DB 仍是 [];save(\"x2\").subscribe() 才写入,DB=[x2]。在 map 里调用返回 Mono 的 audit(x) 并丢掉返回值:audit 没有执行,只有结果 p;改成 flatMap(x -> audit(x).thenReturn(x)):audit 执行了;doOnNext(x -> audit(x)) 同样丢了返回值,audit 没有执行;doOnNext(x -> audit(x).subscribe()) 执行了,但脱离了主链(主链不等它完成,它的错误也传不回主链)。方法返回 Mono 的,返回值必须接到链上。", t=tl(S(3)), mark=lidx(S(3), 'DB = []', '在 map 里调用', 'doOnNext(x -> audit(x))(同样丢了返回值)'), done=lidx(S(3), 'DB = [x2]', 'flatMap(x -> audit(x).thenReturn(x))', '手动订阅'), b=bars([['不订阅 save("x1") 写入的条数', 0, '0'], ['map / doOnNext 里丢掉 audit 的执行次数', 0, '0'], ['flatMap 接上 audit 的执行次数', 1, '1']], 1, mark=[0, 1], done=[2]), kv=KV([['返回 Mono 的方法', '不订阅就没有副作用'], ['map / doOnNext 里调用', '丢了返回值,没有执行'], ['正确接法', 'flatMap(...) 或 then(...)'], ['在 doOnNext 里 subscribe()', '脱离主链,不等待、错误传不回来']], ['返回 Mono 的方法'])),
    step("热源与订阅时机。Sinks.many().multicast().onBackpressureBuffer() 先发 1、2 再订阅、再发 3:订阅者收到 1、2、3——第一个订阅者到来前的事件被缓存了,没有丢。directBestEffort 同样先发 1、2:订阅者只收到 3,前面发的 1 和 2 丢了。replay().all():订阅者收到 1、2、3。Flux.interval 是冷源:订阅者 A 先订阅、B 晚 150 ms 订阅,B 也从 0 开始收到 0、1、2,不是接着 A 的进度。", t=tl(S(4)), mark=lidx(S(4), 'directBestEffort', '订阅者收到 3'), done=lidx(S(4), 'multicast 先发', 'replay().all()', 'B 收到 0'), b=bars([['onBackpressureBuffer 订阅者收到的事件数', 3, '3(缓存了)'], ['directBestEffort 订阅者收到的事件数', 1, '1(丢了 2 个)'], ['replay().all() 订阅者收到的事件数', 3, '3']], 3, mark=[1], done=[0, 2]), kv=KV([['multicast + onBackpressureBuffer', '第一个订阅者前的事件被缓存'], ['directBestEffort', '没有订阅者时发的事件丢弃'], ['replay', '新订阅者重放历史'], ['Flux.interval', '冷源,每个订阅者从头开始']], ['directBestEffort'])),
    step("看起来惰性、其实已经开始了:CompletableFuture。CompletableFuture.supplyAsync(...) 一构造任务就在 ForkJoinPool.commonPool-worker-1 上执行了;Mono.fromFuture(cf) 构造并没有触发它,它早已执行。Mono.fromFuture(Supplier) 才是惰性的:构造时不执行,订阅(block())时任务才执行。订阅 2 次 Mono.fromFuture(cf),两个订阅者收到同一个已完成的结果 cf,没有重新执行。把已经在跑的 Future 包成 Mono 不会让它变惰性。", t=tl(S(5)), mark=lidx(S(5), 'future 的任务在', '早已执行'), done=lidx(S(5), '惰性的 future 任务被执行', '收到 cf'), b=bars([['supplyAsync 构造后立刻执行的任务数', 1, '1'], ['Mono.fromFuture(Supplier) 构造后执行的任务数', 0, '0'], ['订阅 2 次 fromFuture(cf) 的任务执行次数', 0, '0(不重新执行)']], 1, mark=[0], done=[1, 2]), kv=KV([['CompletableFuture', 'eager,构造时就开始'], ['Mono.fromFuture(future)', '不能让 future 变惰性'], ['Mono.fromFuture(Supplier)', '惰性,订阅时才创建 future'], ['多次订阅', '共用同一个结果']], ['CompletableFuture'])),
    step("订阅的方式。subscribe() 不等待:调用 Mono.delay(300 ms).subscribe(...) 在 1 ms 就返回,300 ms 后才在另一个线程完成。block() 会等:305 ms 后返回,出错时抛出异常(IllegalStateException: boom)。没有 error 回调的 subscribe():Mono.error(...).subscribe() 正常返回,不抛异常,Reactor 只在日志里打一行 [ERROR] Operator called default onErrorDropped - ErrorCallbackNotImplemented: IllegalStateException: boom2,错误被吞到日志里;带 error 回调的 subscribe(onNext, onError) 才能收到错误。", t=tl(S(6)), mark=lidx(S(6), 'subscribe() 正常返回', 'onErrorDropped'), done=lidx(S(6), 'subscribe() 返回,用时 1 ms', 'block() 返回,用时', 'block() 抛出', 'onError 收到'), b=bars([['subscribe() 返回用时 ms', 1, '1'], ['block() 返回用时 ms', 305, '305'], ['没有 error 回调时抛给调用方的异常数', 0, '0(只在日志里)']], 305, done=[0, 1], mark=[2]), kv=KV([['subscribe()', '立即返回,不等待'], ['block()', '等待,异常抛给调用线程'], ['没有 error 回调', '错误只打日志,调用方不知道'], ['建议', '链的末端交给框架订阅,或写 error 回调']], ['没有 error 回调'])),
]
